+      observed_count: counts.locator_coverage.page_or_exact_located_count,
+      required_count: requiredFullBetaLocatedRows,
+      coverage_ratio: counts.locator_coverage.page_or_exact_coverage_ratio,
+      threshold: LOCATOR_LAUNCH_COVERAGE_THRESHOLD,
+      reason: 'Full beta cannot hide document_only, ambiguous, or manual-review locator blockers.',
+    },
+    {
+      blocker_id: 'full_9709_beta:remaining_locator_blockers',
+      scope: 'full_9709_beta',
+      severity: 'blocking',
+      document_only_row_count: blockerSummary.document_only_row_count,
+      ambiguous_row_count: blockerSummary.ambiguous_row_count,
+      needs_manual_review_row_count: blockerSummary.needs_manual_review_row_count,
+      missing_ms_row_count: blockerSummary.missing_ms_row_count,
+      reason: 'Rows remain available at runtime, but unlocated MS reveal degrades to fallback/review.',
+    },
+    {
+      blocker_id: 'full_9709_beta:visual_qa_failed_or_blocked_assets',
+      scope: 'full_9709_beta',
+      severity: 'blocking',
+      visual_qa_fail_asset_count: blockerSummary.visual_qa_fail_asset_count,
+      visual_qa_blocked_asset_count: blockerSummary.visual_qa_blocked_asset_count,
+      reason: 'Full beta must not promote failed or blocked visual-QA assets to student display.',
+    },
+    {
+      blocker_id: 'public_launch:separate_policy_legal_release_authorization_required',
+      scope: 'public_launch',
+      severity: 'blocking',
+      reason: 'Public launch requires a separate policy/legal/release authorization artifact.',
+    },
+  ];
+}
+
+function sumSideEffectCounts(...receipts) {
+  const sum = {};
+  for (const field of ZERO_SIDE_EFFECT_FIELDS) sum[field] = 0;
+  for (const receipt of receipts) {
+    if (!isRecord(receipt)) continue;
+    for (const field of ZERO_SIDE_EFFECT_FIELDS) {
+      sum[field] += numberFrom(receipt[field]);
+    }
+    sum.production_rag_vector_mutation_count +=
+      numberFrom(receipt.production_rag_reindex_count) +
+      numberFrom(receipt.vector_mutation_count) +
+      numberFrom(receipt.rag_vector_mutation_count) +
+      numberFrom(receipt.rag_reindex_count);
+    sum.external_model_call_count +=
+      numberFrom(receipt.external_llm_model_call_count) +
+      numberFrom(receipt.external_ocr_vlm_model_call_count);
+  }
+  sum.side_effect_total_count = ZERO_SIDE_EFFECT_FIELDS.reduce((total, field) => total + numberFrom(sum[field]), 0);
+  return sum;
+}
+
+function buildSideEffectReceipt(inputs) {
+  return sumSideEffectCounts(
+    inputs.runtime_readiness_boundary?.side_effect_receipt,
+    inputs.locator_backfill_harness?.side_effect_receipt,
+    inputs.locator_backfill_all_3530?.side_effect_receipt,
+    inputs.visual_qa_receipt?.side_effect_receipt,
+    inputs.product_display_posture?.side_effect_receipt,
+    inputs.runtime_route_receipt?.side_effect_receipt,
+    inputs.frontend_integration_receipt?.side_effect_receipt,
+    inputs.self_assessment_runtime_receipt?.side_effect_receipt,
+    inputs.runtime_rehearsal_receipt?.side_effect_receipt,
+    inputs.launch_rehearsal?.side_effect_receipt,
+  );
+}
+
+function buildProductionCutoverPlan(counts) {
+  return {
+    cutover_authorization_status: 'future_authorization_required',
+    production_mutation_allowed_by_this_artifact: false,
+    required_commands: [
+      'npm run workflow:codex-preflight -- --json',
+      'node scripts/method-map/build-post-attempt-ms-page-locator-backfill-all-3530.mjs',
+      'npm run method-map:build-post-attempt-ms-page-screenshot-assets',
+      'npm run method-map:build-post-attempt-ms-page-screenshot-visual-qa',
+      'npm run method-map:build-post-attempt-ms-source-reveal-product-display-posture',
+      'node scripts/method-map/build-post-attempt-ms-reveal-runtime-rehearsal.mjs',
+      'node scripts/method-map/build-post-attempt-ms-reveal-launch-rehearsal.mjs',
+      'node scripts/method-map/build-post-attempt-ms-reveal-runtime-final-closeout.mjs',
+    ],
+    expected_counts: {
+      runtime_rows: counts.total_runtime_row_count,
+      page_or_exact_located_rows: counts.locator_coverage.page_or_exact_located_count,
+      document_only_rows: counts.locator_coverage.document_only_count,
+      ambiguous_rows: counts.locator_coverage.ambiguous_count,
+      needs_manual_review_rows: counts.locator_coverage.needs_manual_review_count,
+      controlled_page_screenshot_assets: counts.screenshot_assets.unique_page_screenshot_asset_count,
+      generated_screenshots: counts.screenshot_assets.generated_screenshot_count,
+      visual_qa_pass_assets: counts.visual_qa.pass_count,
+      visual_qa_fail_assets: counts.visual_qa.fail_count,
+      visual_qa_blocked_assets: counts.visual_qa.blocked_count,
+      student_display_eligible_assets: counts.student_display.eligible_asset_count,
+      student_display_eligible_rows: counts.student_display.eligible_row_count,
+    },
+    required_human_authorization_points: [
+      'Authorize remote disposable storage rehearsal.',
+      'Authorize remote disposable Supabase rehearsal.',
+      'Authorize production storage upload/import.',
+      'Authorize production Supabase mutation/import.',
+      'Authorize any release-scope widening beyond internal/scoped alpha.',
+      'Authorize separate policy/legal/release approval before public launch.',
+      'Authorize any RAG/vector reindexing in a separate issue.',
+    ],
+    rollback_plan: {
+      feature_flag_default: 'disabled',
+      rollback_scope_key_required: true,
+      rollback_scope_key: 'ms_source_reveal_cutover_batch_id',
+      storage_rollback: 'Delete only objects under the authorized cutover batch prefix.',
+      supabase_rollback: 'Delete only rows carrying the cutover batch id after exporting rollback receipts.',
+      route_rollback: 'Disable v1_ms_source_reveal_runtime and return unavailable/fallback display for MS source reveal.',
+      rag_reindex_rollback_required: false,
+    },
+    monitoring_smoke_checks: [
+      'Verify 3530 runtime rows load with zero missing rows.',
+      'Verify 424 controlled screenshot assets and 0 public/static asset URLs.',
+      'Verify pre-attempt asset fetches remain blocked.',
+      'Verify post-attempt eligible reveal fetch succeeds for 28 rows.',
+      'Verify document_only, ambiguous, and needs_manual_review rows degrade to fallback/review.',
+      'Verify mobile readability pass count remains >= 6 and p95 reveal-route latency is refreshed in staging.',
+      'Verify no production Supabase, storage, RAG/vector, OCR/VLM, external model, scoring, or Smart Mark mutation occurs without explicit authorization.',
+    ],
+    disable_takedown_controls: {
+      feature_flag: 'v1_ms_source_reveal_runtime',
+      global_disable_required: true,
+      per_asset_disable_required: true,
+      takedown_control_required: true,
+      public_static_directory_deployment_allowed: false,
+      disable_action_expected_effect: 'Route returns fallback/unavailable; existing runtime rows remain preserved.',
+    },
+  };
+}
+
+function withContentHash(closeout) {
+  const clone = { ...closeout };
+  delete clone.content_hash;
+  return { ...closeout, content_hash: sha256Value(clone) };
+}
+
+function checkPass(id, passed, summary, observed = {}) {
+  return { id, status: passed ? 'pass' : 'fail', summary, observed };
+}
+
+function sourceArtifactsPresent(closeout, errors) {
+  const refs = asArray(closeout.source_artifacts);
+  const roles = refs.map((ref) => ref?.role);
+  const missingRoles = SOURCE_INPUTS.map(([role]) => role).filter((role) => !roles.includes(role));
+  if (missingRoles.length > 0) {
+    errors.push(`source_artifact_roles_missing:${missingRoles.join(',')}`);
+  }
+  const malformedRefs = refs.filter((ref) => (
+    ref?.exists !== true ||
+    ref?.loaded !== true ||
+    !/^[a-f0-9]{64}$/u.test(String(ref?.sha256))
+  ));
+  for (const ref of malformedRefs) {
+    errors.push(`source_artifact_missing_or_malformed:${ref?.role ?? 'unknown'}`);
+  }
+  return missingRoles.length === 0 && malformedRefs.length === 0;
+}
+
+function upstreamValidatorsPass(closeout, errors) {
+  const statuses = closeout.upstream_validator_statuses ?? {};
+  const failures = Object.entries(statuses).filter(([, status]) => status !== 'pass');
+  for (const [role, status] of failures) {
+    errors.push(`upstream_validator_not_pass:${role}:${status}`);
+  }
+  return failures.length === 0 && Object.keys(statuses).length === 11;
+}
+
+function liveIssueChainPass(closeout) {
+  const issues = asArray(closeout.live_github_chain?.issues);
+  const childIssuesPass = issues
+    .filter((issue) => issue.issue >= 1487 && issue.issue <= 1497)
+    .length === DEPENDS_ON_ISSUES.length &&
+    issues
+      .filter((issue) => issue.issue >= 1487 && issue.issue <= 1497)
+      .every((issue) => issue.state === 'CLOSED' && issue.pr_state === 'MERGED' && typeof issue.pr === 'number');
+  const currentIssue = issues.find((issue) => issue.issue === ISSUE);
+  return childIssuesPass && currentIssue?.state === 'OPEN';
+}
+
+function finalCountsComplete(closeout, errors) {
+  const counts = closeout.final_counts ?? {};
+  const pass =
+    counts.total_runtime_row_count === EXPECTED_ROW_COUNT &&
+    counts.row_coverage?.observed_runtime_row_count === EXPECTED_ROW_COUNT &&
+    counts.row_coverage?.missing_runtime_row_count === 0 &&
+    counts.locator_coverage?.page_or_exact_located_count === 635 &&
+    counts.locator_coverage?.document_only_count === 1563 &&
+    counts.locator_coverage?.ambiguous_count === 1058 &&
+    counts.locator_coverage?.needs_manual_review_count === 274 &&
+    counts.screenshot_assets?.unique_page_screenshot_asset_count === 424 &&
+    counts.screenshot_assets?.generated_screenshot_count === 424 &&
+    counts.visual_qa?.pass_count === 407 &&
+    counts.visual_qa?.fail_count === 6 &&
+    counts.visual_qa?.blocked_count === 11 &&
+    counts.student_display?.eligible_asset_count === 25 &&
+    counts.student_display?.eligible_row_count === 28;
+  if (!pass) errors.push('final_counts_missing_or_unexpected');
+  return pass;
+}
+
+function scopedVerdictsPass(closeout, errors) {
+  const verdict = closeout.launch_readiness_verdict;
+  if (!isRecord(verdict)) {
+    errors.push('launch_readiness_verdict_not_scoped_object');
+    errors.push('only_one_undifferentiated_launch_verdict_emitted');
+    return false;
+  }
+  const scopedValues = new Set(['ready', 'ready_with_exceptions', 'blocked']);
+  const publicValues = new Set(['not_authorized', 'blocked', 'future_authorization_required']);
+  const pass =
+    scopedValues.has(verdict.scoped_alpha) &&
+    scopedValues.has(verdict.full_9709_beta) &&
+    publicValues.has(verdict.public_launch) &&
+    closeout.single_undifferentiated_launch_verdict_emitted === false;
+  if (!pass) errors.push('scoped_launch_verdicts_missing_or_invalid');
+  return pass;
+}
+
+function nonReadyVerdictsHaveBlockers(closeout, errors) {
+  const verdict = closeout.launch_readiness_verdict;
+  const blockers = asArray(closeout.blockers);
+  const nonReady =
+    !isRecord(verdict) ||
+    verdict.scoped_alpha !== 'ready' ||
+    verdict.full_9709_beta !== 'ready' ||
+    verdict.public_launch !== 'not_authorized';
+  const pass = !nonReady || blockers.length > 0;
+  if (!pass) errors.push('non_ready_verdicts_missing_blockers');
+  return pass;
+}
+
+function publicLaunchNotReady(closeout, errors) {
+  const verdict = closeout.launch_readiness_verdict;
+  if (!isRecord(verdict)) return true;
+  const pass = verdict.public_launch !== 'ready';
+  if (!pass) errors.push('public_launch_marked_ready_without_authorization');
+  return pass;
+}
+
+function fullBetaBlockersVisible(closeout, errors) {
+  const verdict = closeout.launch_readiness_verdict;
+  const locatorBlockerCount = asArray(closeout.blocker_inventory?.locator_blockers).length;
+  const visualBlockerCount = asArray(closeout.blocker_inventory?.visual_qa_asset_blockers).length;
+  const pass = isRecord(verdict) &&
+    verdict.full_9709_beta === 'blocked' &&
+    locatorBlockerCount === 2895 &&
+    visualBlockerCount === 17 &&
+    closeout.blocker_summary?.document_only_row_count === 1563 &&
+    closeout.blocker_summary?.ambiguous_row_count === 1058 &&
+    closeout.blocker_summary?.needs_manual_review_row_count === 274;
+  if (!pass) errors.push('full_beta_blockers_hidden');
+  return pass;
+}
+
+function sideEffectsZero(closeout, errors) {
+  const receipt = closeout.side_effect_receipt ?? {};
+  const nonZeroFields = ZERO_SIDE_EFFECT_FIELDS.filter((field) => numberFrom(receipt[field]) !== 0);
+  for (const field of nonZeroFields) {
+    errors.push(`${field}_not_zero`);
+  }
+  if (numberFrom(receipt.side_effect_total_count) !== 0) {
+    errors.push('side_effect_total_count_not_zero');
+  }
+  return nonZeroFields.length === 0 && numberFrom(receipt.side_effect_total_count) === 0;
+}
+
+function cutoverPlanComplete(closeout, errors) {
+  const plan = closeout.production_cutover_plan ?? {};
+  const pass =
+    plan.cutover_authorization_status === 'future_authorization_required' &&
+    plan.production_mutation_allowed_by_this_artifact === false &&
+    asArray(plan.required_commands).includes('npm run workflow:codex-preflight -- --json') &&
+    numberFrom(plan.expected_counts?.runtime_rows) === EXPECTED_ROW_COUNT &&
+    numberFrom(plan.expected_counts?.controlled_page_screenshot_assets) === 424 &&
+    asArray(plan.required_human_authorization_points).length >= 5 &&
+    plan.rollback_plan?.feature_flag_default === 'disabled' &&
+    plan.disable_takedown_controls?.feature_flag === 'v1_ms_source_reveal_runtime';
+  if (!pass) errors.push('production_cutover_plan_missing_or_incomplete');
+  return pass;
+}
+
+export function validatePostAttemptMsRevealRuntimeFinalCloseout({ closeout = null } = {}) {
+  const c = isRecord(closeout) ? closeout : {};
+  const errors = [];
+  if (closeout !== null && closeout !== undefined && !isRecord(closeout)) {
+    errors.push('closeout_not_a_record');
+  }
+  for (const diagnostic of asArray(c.input_diagnostics)) {
+    if (diagnostic?.code) errors.push(`${diagnostic.code}:${diagnostic.role ?? 'unknown_input'}`);
+  }
+
+  const checks = [
+    checkPass('source_artifacts_present', sourceArtifactsPresent(c, errors), 'Every #1487-#1497 source artifact is present and hashable.'),
+    checkPass('upstream_validators_pass', upstreamValidatorsPass(c, errors), 'Every upstream validator artifact reports pass.'),
+    checkPass('live_issue_chain_closed_and_merged', liveIssueChainPass(c), 'Issues #1487-#1497 are closed by merged PRs and #1498 remains open.'),
+    checkPass('final_counts_complete', finalCountsComplete(c, errors), 'Required final launch-readiness count categories are complete.'),
+    checkPass('scoped_launch_verdicts_present', scopedVerdictsPass(c, errors), 'Launch readiness is split into scoped_alpha, full_9709_beta, and public_launch verdicts.'),
+    checkPass('non_ready_verdicts_have_blockers', nonReadyVerdictsHaveBlockers(c, errors), 'Any non-ready verdict has machine-readable blockers.'),
+    checkPass('public_launch_not_ready_without_authorization', publicLaunchNotReady(c, errors), 'Public launch is not marked ready without separate authorization.'),
+    checkPass('full_beta_blockers_visible', fullBetaBlockersVisible(c, errors), 'Full beta blockers expose locator, visual-QA, and display-scope blockers.'),
+    checkPass('side_effect_counts_zero', sideEffectsZero(c, errors), 'Forbidden production/storage/RAG/vector/model/scoring side-effect counts are zero.'),
+    checkPass('production_cutover_plan_complete', cutoverPlanComplete(c, errors), 'Production cutover plan includes commands, counts, authorization points, rollback, smoke, and disable controls.'),
+  ];
+  for (const check of checks.filter((item) => item.status === 'fail')) {
+    errors.push(`check_failed:${check.id}`);
+  }
+  const uniqueErrors = [...new Set(errors)];
+  const status = uniqueErrors.length === 0 ? 'pass' : 'fail';
+  return {
+    schema_version: 'post_attempt_ms_reveal_runtime_final_closeout.validator_result.v1',
+    generated_at: c.generated_at ?? GENERATED_AT,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    validator_status: status,
+    summary: {
+      validation_status: status,
+      scoped_alpha: isRecord(c.launch_readiness_verdict) ? c.launch_readiness_verdict.scoped_alpha ?? null : null,
+      full_9709_beta: isRecord(c.launch_readiness_verdict) ? c.launch_readiness_verdict.full_9709_beta ?? null : null,
+      public_launch: isRecord(c.launch_readiness_verdict) ? c.launch_readiness_verdict.public_launch ?? null : null,
+      blocker_count: asArray(c.blockers).length,
+      locator_blocker_count: asArray(c.blocker_inventory?.locator_blockers).length,
+      visual_qa_asset_blocker_count: asArray(c.blocker_inventory?.visual_qa_asset_blockers).length,
+      side_effect_total_count: numberFrom(c.side_effect_receipt?.side_effect_total_count),
+      check_fail_count: checks.filter((check) => check.status === 'fail').length,
+    },
+    checks,
+    errors: uniqueErrors,
+  };
+}
+
+function buildReadback(closeout, validatorResult) {
+  const counts = closeout.final_counts;
+  const lines = [
+    '# Post-Attempt MS Reveal Runtime Final Closeout',
+    '',
+    `Issue: #${ISSUE}`,
+    `Parent: #${PARENT_ISSUE}`,
+    `Depends on: #${DEPENDS_ON_ISSUES.join(', #')}`,
+    `Validation status: \`${validatorResult.validator_status}\``,
+    '',
+    '## Launch Readiness Verdict',
+    '',
+    `- scoped_alpha: \`${closeout.launch_readiness_verdict.scoped_alpha}\``,
+    `- full_9709_beta: \`${closeout.launch_readiness_verdict.full_9709_beta}\``,
+    `- public_launch: \`${closeout.launch_readiness_verdict.public_launch}\``,
+    '',
+    '## Final Counts',
+    '',
+    `- total_runtime_row_count: \`${counts.total_runtime_row_count}\``,
+    `- page_or_exact_located_count: \`${counts.locator_coverage.page_or_exact_located_count}\``,
+    `- document_only_count: \`${counts.locator_coverage.document_only_count}\``,
+    `- ambiguous_count: \`${counts.locator_coverage.ambiguous_count}\``,
+    `- needs_manual_review_count: \`${counts.locator_coverage.needs_manual_review_count}\``,
+    `- unique_page_screenshot_asset_count: \`${counts.screenshot_assets.unique_page_screenshot_asset_count}\``,
+    `- generated_screenshot_count: \`${counts.screenshot_assets.generated_screenshot_count}\``,
+    `- visual_qa_pass_count: \`${counts.visual_qa.pass_count}\``,
+    `- visual_qa_fail_count: \`${counts.visual_qa.fail_count}\``,
+    `- visual_qa_blocked_count: \`${counts.visual_qa.blocked_count}\``,
+    `- student_display_eligible_asset_count: \`${counts.student_display.eligible_asset_count}\``,
+    `- student_display_eligible_row_count: \`${counts.student_display.eligible_row_count}\``,
+    '',
+    '## Side Effects',
+    '',
+    `- production_supabase_mutation_count: \`${closeout.side_effect_receipt.production_supabase_mutation_count}\``,
+    `- production_storage_mutation_count: \`${closeout.side_effect_receipt.production_storage_mutation_count}\``,
+    `- production_rag_reindex_count: \`${closeout.side_effect_receipt.production_rag_reindex_count}\``,
+    `- external_model_call_count: \`${closeout.side_effect_receipt.external_model_call_count}\``,
+    '',
+    '## Blockers',
+    '',
+    ...closeout.blockers.map((blocker) => `- ${blocker.blocker_id}: ${blocker.severity}`),
+    '',
+    '## Production Cutover Plan',
+    '',
+    `- authorization_status: \`${closeout.production_cutover_plan.cutover_authorization_status}\``,
+    `- production_mutation_allowed_by_this_artifact: \`${closeout.production_cutover_plan.production_mutation_allowed_by_this_artifact}\``,
+    `- feature_flag: \`${closeout.production_cutover_plan.disable_takedown_controls.feature_flag}\``,
+    '',
+    '## Validator Checks',
+    '',
+    ...validatorResult.checks.map((check) => `- ${check.id}: ${check.status}`),
+    '',
+  ];
+  return lines.join('\n');
+}
+
+export function buildPostAttemptMsRevealRuntimeFinalCloseout(options = {}) {
+  const root = options.root ?? repoRootFromScript();
+  const paths = pathsFromOptions(options);
+  const generatedAt = options.generatedAt ?? GENERATED_AT;
+  const { diagnostics, inputs } = loadInputs(root, paths);
+  const sourceArtifacts = buildSourceArtifacts(root, paths, inputs);
+  const finalCounts = buildFinalCounts(inputs);
+  const blockerInventory = buildBlockerInventory(inputs);
+  const blockerSummary = buildBlockerSummary(finalCounts, blockerInventory);
+  const sideEffectReceipt = buildSideEffectReceipt(inputs);
+  const blockers = buildBlockers(finalCounts, blockerSummary);
+  const closeout = withContentHash({
+    schema_version: 'post_attempt_ms_reveal_runtime_final_closeout.v1',
+    generated_at: generatedAt,
+    generated_by: SCRIPT_NAME,
+    issue: ISSUE,
+    parent_issue: PARENT_ISSUE,
+    depends_on_issues: [...DEPENDS_ON_ISSUES],
+    subject_code: SUBJECT_CODE,
+    artifact_only: true,
+    production_mutation_performed: false,
+    external_model_calls_performed: false,
+    objective:
+      'Close out the V1 post-attempt MS reveal runtime chain with scoped launch-readiness verdicts, final counts, blockers, and a production cutover plan.',
+    required_first_command_receipt: {
+      command: 'npm run workflow:codex-preflight -- --json',
+      completed_before_closeout_build: true,
+      observed_top_status: 'warning',
+      blocking_preflight_failure: false,
+    },
+    source_artifacts: sourceArtifacts,
+    upstream_validator_statuses: buildUpstreamValidatorStatuses(inputs),
+    input_diagnostics: diagnostics,
+    live_github_chain: buildLiveGithubChain(),
+    final_counts: finalCounts,
+    launch_readiness_verdict: {
+      scoped_alpha: 'ready_with_exceptions',
+      full_9709_beta: 'blocked',
+      public_launch: 'future_authorization_required',
+    },
+    single_undifferentiated_launch_verdict_emitted: false,
+    verdict_explanations: {
+      scoped_alpha:
+        'Ready with explicit exceptions for a controlled scoped cohort because route/UI/network smoke, local runtime rehearsal, zero pre-attempt exposure, zero production side effects, and 25 QA-passed internal-scope assets covering 28 rows are present; exceptions are limited coverage and future remote/production authorization.',
+      full_9709_beta:
+        'Blocked: only 635 of 3530 rows have page/exact locator coverage, 2895 locator rows remain document_only/ambiguous/manual-review, and 17 generated screenshot assets failed or were blocked by visual QA.',
+      public_launch:
+        'Future authorization required: no separate policy/legal/release authorization artifact exists, and public launch remains explicitly outside this production-mutation-free closeout.',
+    },
+    blocker_summary: blockerSummary,
+    blocker_inventory: blockerInventory,
+    blockers,
+    production_cutover_plan: buildProductionCutoverPlan(finalCounts),
+    side_effect_receipt: sideEffectReceipt,
+    output_artifacts: {
+      closeout: paths.closeoutOut,
+      validator: paths.validatorOut,
+      readback: paths.readbackOut,
+    },
+  });
+  const validatorResult = validatePostAttemptMsRevealRuntimeFinalCloseout({ closeout });
+  const readback = buildReadback(closeout, validatorResult);
+  return { closeout, validatorResult, readback };
+}
+
+export function writePostAttemptMsRevealRuntimeFinalCloseoutArtifacts({
+  outRoot = repoRootFromScript(),
+  artifacts = null,
+} = {}) {

body:
![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

When destructuring function parameters, destructure from `params || {}` rather than relying solely on parameter defaults like `function foo({ bar } = {})` if the function can be called with an explicit `null`. This prevents a destructuring `TypeError` and allows the `null` input to reach internal validation logic.

```suggestion
export function writePostAttemptMsRevealRuntimeFinalCloseoutArtifacts(params) {
  const {
    outRoot = repoRootFromScript(),
    artifacts = null,
  } = params || {};
```

<details>
<summary>References</summary>

1. When destructuring function parameters, destructure from params || {} rather than relying solely on parameter defaults like function foo({ bar } = {}) if the function can be called with an explicit null. This prevents a destructuring TypeError and allows the null input to reach internal validation logic.
</details>

