When validating that an array contains a complete set of expected elements, explicitly verify the presence and state of each expected element rather than filtering and checking only the elements present in the array. Normalize the input collection using an array helper (e.g., `asArray`), filter out non-record entries, and ensure only entries with a non-empty ID string are indexed to prevent malformed or empty keys.

```javascript
function sourceArtifactsPresent(closeout, errors) {
  const refs = asArray(closeout.source_artifacts).filter(isRecord);
  const refMap = new Map();
  for (const ref of refs) {
    if (typeof ref.role === 'string' && ref.role !== '') {
      refMap.set(ref.role, ref);
    }
  }
  let allPresentAndValid = true;

  for (const [role] of SOURCE_INPUTS) {
    const ref = refMap.get(role);
    if (!ref) {
      errors.push('source_artifact_missing:' + role);
      allPresentAndValid = false;
    } else if (
      ref.exists !== true ||
      ref.loaded !== true ||
      !/^[a-f0-9]{64}$/u.test(String(ref.sha256))
    ) {
      errors.push('source_artifact_missing_or_malformed:' + role);
      allPresentAndValid = false;
    }
  }
  return allPresentAndValid;
}
