  'launch_rehearsal_validator',
];

function upstreamValidatorsPass(closeout, errors) {
  const statuses = closeout.upstream_validator_statuses ?? {};
  let allPass = true;
  for (const role of EXPECTED_VALIDATOR_ROLES) {
    if (statuses[role] !== 'pass') {
      errors.push('upstream_validator_not_pass:' + role + ':' + (statuses[role] ?? 'missing'));
      allPass = false;
    }
  }
  for (const role of Object.keys(statuses)) {
    if (!EXPECTED_VALIDATOR_ROLES.includes(role)) {
      errors.push('upstream_validator_unexpected:' + role);
      allPass = false;
    }
  }
  return allPass;
}
